DROP VIEW IF EXISTS learninsurancedb.vw_vehicles CASCADE;
CREATE VIEW learninsurancedb.vw_vehicles AS
SELECT t.*,
       c.full_name AS customer_name, c.customer_code
FROM learninsurancedb.vehicles t
JOIN learninsurancedb.customers c ON c.id = t.customer_id;

-- LIST: search + filters + sort + paging. Returns { items, totalCount, page, pageSize }
DROP FUNCTION IF EXISTS learninsurancedb.fn_vehicle_get_all(text, int, int, text, text, jsonb);
CREATE FUNCTION learninsurancedb.fn_vehicle_get_all(
    p_search    text  DEFAULT NULL,
    p_page      int   DEFAULT 1,
    p_page_size int   DEFAULT 10,
    p_sort_by   text  DEFAULT NULL,
    p_sort_dir  text  DEFAULT NULL,
    p_filters   jsonb DEFAULT '{}'::jsonb
) RETURNS jsonb
LANGUAGE plpgsql STABLE AS $fn$
DECLARE
    v_page   int := GREATEST(COALESCE(p_page, 1), 1);
    v_size   int := LEAST(GREATEST(COALESCE(p_page_size, 10), 1), 500);
    v_sort   text := learninsurancedb.fn_to_snake(p_sort_by);
    v_dir    text := CASE WHEN lower(COALESCE(p_sort_dir, 'DESC')) = 'asc' THEN 'ASC' ELSE 'DESC' END;
    v_where  text := 'WHERE TRUE';
    v_like   text;
    v_key    text;
    v_val    text;
    v_col    text;
    v_total  bigint;
    v_items  jsonb;
BEGIN
    IF v_sort IS NULL OR NOT (v_sort = ANY (ARRAY['registration_no', 'customer_id', 'vehicle_type', 'make', 'model', 'variant', 'fuel_type', 'manufacture_year', 'registration_date', 'engine_no', 'chassis_no', 'cubic_capacity', 'seating_capacity', 'id', 'created_date', 'modified_date', 'is_active', 'customer_name'])) THEN
        v_sort := 'created_date';
        IF p_sort_by IS NULL THEN v_dir := 'DESC'; END IF;
    END IF;

    IF p_search IS NOT NULL AND btrim(p_search) <> '' THEN
        v_like := '%' || btrim(p_search) || '%';
        v_where := v_where || format(' AND (registration_no::text ILIKE %1$L OR make::text ILIKE %1$L OR model::text ILIKE %1$L OR customer_name::text ILIKE %1$L OR engine_no::text ILIKE %1$L OR chassis_no::text ILIKE %1$L)', v_like);
    END IF;

    FOR v_key, v_val IN SELECT key, value FROM jsonb_each_text(COALESCE(p_filters, '{}'::jsonb)) LOOP
        v_col := learninsurancedb.fn_to_snake(v_key);
        IF v_col = ANY (ARRAY['is_active', 'vehicle_type', 'customer_id', 'fuel_type', 'make']) AND COALESCE(v_val, '') <> '' THEN
            v_where := v_where || format(' AND %I::text = %L', v_col, v_val);
        END IF;
    END LOOP;

    EXECUTE format('SELECT count(*) FROM learninsurancedb.vw_vehicles %s', v_where) INTO v_total;
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(learninsurancedb.fn_to_camel(to_jsonb(q))), ''[]''::jsonb)
         FROM (SELECT * FROM learninsurancedb.vw_vehicles %s ORDER BY %I %s, id DESC LIMIT %s OFFSET %s) q',
        v_where, v_sort, v_dir, v_size, (v_page - 1) * v_size) INTO v_items;

    RETURN jsonb_build_object('items', v_items, 'totalCount', v_total, 'page', v_page, 'pageSize', v_size);
END
$fn$;

-- GET BY ID: returns the row as JSON, or NULL when not found
CREATE OR REPLACE FUNCTION learninsurancedb.fn_vehicle_get_by_id(p_id bigint) RETURNS jsonb
LANGUAGE sql STABLE AS $fn$
    SELECT learninsurancedb.fn_to_camel(to_jsonb(v)) FROM learninsurancedb.vw_vehicles v WHERE v.id = p_id;
$fn$;

-- CREATE: p_data uses camelCase keys
CREATE OR REPLACE FUNCTION learninsurancedb.fn_vehicle_create(p_data jsonb, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
DECLARE v_id bigint;
BEGIN
    INSERT INTO learninsurancedb.vehicles (registration_no, customer_id, vehicle_type, make, model, variant, fuel_type, manufacture_year, registration_date, engine_no, chassis_no, cubic_capacity, seating_capacity, created_by)
    VALUES (NULLIF(p_data->>'registrationNo', ''),
            NULLIF(p_data->>'customerId', '')::bigint,
            NULLIF(p_data->>'vehicleType', ''),
            NULLIF(p_data->>'make', ''),
            NULLIF(p_data->>'model', ''),
            NULLIF(p_data->>'variant', ''),
            NULLIF(p_data->>'fuelType', ''),
            NULLIF(p_data->>'manufactureYear', '')::int,
            NULLIF(p_data->>'registrationDate', '')::date,
            NULLIF(p_data->>'engineNo', ''),
            NULLIF(p_data->>'chassisNo', ''),
            NULLIF(p_data->>'cubicCapacity', '')::int,
            COALESCE(NULLIF(p_data->>'seatingCapacity', '')::int, 5),
            COALESCE(p_user, 'system'))
    RETURNING id INTO v_id;
    RETURN learninsurancedb.fn_vehicle_get_by_id(v_id);
END
$fn$;


-- UPDATE: only keys present in p_data are changed (so partial and full updates both work)
CREATE OR REPLACE FUNCTION learninsurancedb.fn_vehicle_update(p_id bigint, p_data jsonb, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.vehicles SET
        registration_no = CASE WHEN p_data ? 'registrationNo' THEN NULLIF(p_data->>'registrationNo', '') ELSE registration_no END,
        customer_id = CASE WHEN p_data ? 'customerId' THEN NULLIF(p_data->>'customerId', '')::bigint ELSE customer_id END,
        vehicle_type = CASE WHEN p_data ? 'vehicleType' THEN NULLIF(p_data->>'vehicleType', '') ELSE vehicle_type END,
        make = CASE WHEN p_data ? 'make' THEN NULLIF(p_data->>'make', '') ELSE make END,
        model = CASE WHEN p_data ? 'model' THEN NULLIF(p_data->>'model', '') ELSE model END,
        variant = CASE WHEN p_data ? 'variant' THEN NULLIF(p_data->>'variant', '') ELSE variant END,
        fuel_type = CASE WHEN p_data ? 'fuelType' THEN NULLIF(p_data->>'fuelType', '') ELSE fuel_type END,
        manufacture_year = CASE WHEN p_data ? 'manufactureYear' THEN NULLIF(p_data->>'manufactureYear', '')::int ELSE manufacture_year END,
        registration_date = CASE WHEN p_data ? 'registrationDate' THEN NULLIF(p_data->>'registrationDate', '')::date ELSE registration_date END,
        engine_no = CASE WHEN p_data ? 'engineNo' THEN NULLIF(p_data->>'engineNo', '') ELSE engine_no END,
        chassis_no = CASE WHEN p_data ? 'chassisNo' THEN NULLIF(p_data->>'chassisNo', '') ELSE chassis_no END,
        cubic_capacity = CASE WHEN p_data ? 'cubicCapacity' THEN NULLIF(p_data->>'cubicCapacity', '')::int ELSE cubic_capacity END,
        seating_capacity = CASE WHEN p_data ? 'seatingCapacity' THEN COALESCE(NULLIF(p_data->>'seatingCapacity', '')::int, 5) ELSE seating_capacity END,
        modified_date = now(),
        modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Vehicle % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_vehicle_get_by_id(p_id);
END
$fn$;


-- SET ACTIVE: soft delete / restore
CREATE OR REPLACE FUNCTION learninsurancedb.fn_vehicle_set_active(p_id bigint, p_active boolean, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.vehicles SET is_active = p_active, modified_date = now(), modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Vehicle % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_vehicle_get_by_id(p_id);
END
$fn$;

-- DELETE (soft): sets is_active = false
CREATE OR REPLACE FUNCTION learninsurancedb.fn_vehicle_delete(p_id bigint, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    PERFORM learninsurancedb.fn_vehicle_set_active(p_id, FALSE, p_user);
    RETURN jsonb_build_object('id', p_id, 'deleted', TRUE);
END
$fn$;
